* Stimulus
Vinp vp 0 DC 0.9 AC 1 PULSE(0.5 1.3 10n 1n 1n 1u 2u)

.control
  * 1. AC Analysis for Open-Loop Gain, fun, PM
  * The 10uF/100Meg feedback network keeps DC bias stable while allowing open-loop AC measurement.
  ac dec 100 1 1G
  let gain_db = vdb(vout)
  let phase = 180/PI * cph(v(vout))
  meas ac A_OL_dB find gain_db at=1
  meas ac f_un when gain_db=0 fall=1
  meas ac phase_at_fun find phase when gain_db=0 fall=1
  let PM = phase_at_fun + 180
  print A_OL_dB f_un PM

  * 2. Transient Analysis for Slew Rate
  * Convert to unity-gain buffer by altering feedback components
  alter c1 1e-15
  alter r1 1
  tran 1n 2u
  meas tran v_max max v(vout)
  meas tran v_min min v(vout)
  meas tran t_rise1 trig v(vout) val=0.7 rise=1 targ v(vout) val=1.1 rise=1
  let SR_rise = 0.4 / t_rise1
  meas tran t_fall1 trig v(vout) val=1.1 fall=1 targ v(vout) val=0.7 fall=1
  let SR_fall = 0.4 / t_fall1
  print SR_rise SR_fall

  * 3. PSRR+
  * Restore feedback for open-loop AC
  alter c1 1e-5
  alter r1 100e6
  * Move AC source to VDD
  alter @Vinp[ac] = 0
  alter @VDD[ac] = 1
  ac dec 100 1 1G
  let Avdd_db = vdb(vout)
  meas ac Avdd_DC find Avdd_db at=1
  let PSRR_plus = A_OL_dB - Avdd_DC
  print PSRR_plus

  quit
.endc

